<?php

use App\Models\Competence;
use App\Models\JobVacancy;
use App\Models\Question;
use App\Models\Service;
use Illuminate\Database\Migrations\Migration;
use Illuminate\Support\Facades\DB;

/**
 * Replaces English texts that only summarised the German text with complete translations:
 * the privacy policy, the damage form / emergency numbers / change of property management services,
 * the competence texts with their service lists, three job ads, one FAQ answer, the vacancies intro,
 * the intro of the services pages and two texts of the "Verwalterservice" page.
 *
 * An English text is only replaced while it is still the short version (less than 70 percent of the German
 * length) or still has the old wording named for the item, so texts edited in the admin stay untouched.
 */
return new class extends Migration
{
    public function up(): void
    {
        foreach ($this->competences() as $germanName => $fields) {
            Competence::all()
                ->filter(fn (Competence $competence): bool => $competence->getTranslation('name', 'de', false) === $germanName)
                ->each(fn (Competence $competence) => $this->replaceOnModel($competence, $fields));
        }

        foreach ($this->services() as $germanName => $fields) {
            Service::all()
                ->filter(fn (Service $service): bool => $service->getTranslation('name', 'de', false) === $germanName)
                ->each(fn (Service $service) => $this->replaceOnModel($service, $fields));
        }

        foreach ($this->jobs() as $germanTitle => $item) {
            JobVacancy::all()
                ->filter(fn (JobVacancy $vacancy): bool => $vacancy->getTranslation('title', 'de', false) === $germanTitle
                    && str_contains((string) $vacancy->getTranslation('description', 'de', false), $item['marker']))
                ->each(fn (JobVacancy $vacancy) => $this->replaceOnModel($vacancy, ['description' => $item['text']]));
        }

        Question::all()
            ->filter(fn (Question $question): bool => $question->getTranslation('question', 'de', false) === 'Wie finde ich die passende Hausverwaltung für meine Immobilie?')
            ->each(fn (Question $question) => $this->replaceOnModel($question, ['answer' => $this->hausverwaltungAnswer()]));

        foreach ($this->settings() as [$group, $name, $text, $oldStart]) {
            $this->replaceSetting($group, $name, $text, $oldStart);
        }
    }

    public function down(): void
    {
        // Text completion, nothing to restore.
    }

    /**
     * @param  array<string, string>  $fields
     */
    private function replaceOnModel(Competence|Service|JobVacancy|Question $model, array $fields): void
    {
        foreach ($fields as $field => $text) {
            $german = (string) $model->getTranslation($field, 'de', false);
            $english = (string) $model->getTranslation($field, 'en', false);

            if ($german !== '' && $this->isAbridged($german, $english)) {
                $model->setTranslation($field, 'en', $text);
            }
        }

        $model->saveQuietly();
    }

    private function replaceSetting(string $group, string $name, string $text, ?string $oldStart): void
    {
        $german = DB::table('settings')->where('group', $group)->where('name', $name.'_de')->first();
        $english = DB::table('settings')->where('group', $group)->where('name', $name.'_en')->first();

        if (! $german || ! $english) {
            return;
        }

        $current = (string) json_decode($english->payload);
        $replace = $oldStart !== null
            ? str_starts_with(trim(strip_tags($current)), $oldStart)
            : $this->isAbridged((string) json_decode($german->payload), $current);

        if ($replace) {
            DB::table('settings')->where('id', $english->id)->update(['payload' => json_encode($text, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)]);
        }
    }

    private function isAbridged(string $german, string $english): bool
    {
        $length = fn (string $text): int => mb_strlen(trim(preg_replace('/\s+/u', ' ', strip_tags($text))));

        return $length($english) < $length($german) * 0.7;
    }

    /**
     * @return array<int, array{0: string, 1: string, 2: string, 3: string|null}>
     */
    private function settings(): array
    {
        return [
            ['translatable_legal', 'dpgr_text', $this->privacyPolicy(), null],
            ['translatable_vacancies', 'vacancies_introtext', $this->vacanciesIntro(), 'be real offers great professional challenges'],
            ['translatable_leistungen', 'hausverwaltung_leistungen_introtext', $this->servicesIntro(), 'Property management is more than just a job for us'],
            ['translatable_leistungen', 'immobilien_leistungen_introtext', $this->servicesIntro(), 'Property management is more than just a job for us'],
            ['translatable_verwalterservicelandingpage', 'section_1_text', $this->verwalterserviceSectionOne(), null],
            ['translatable_verwalterservicelandingpage', 'hero_headline', 'Our service: we work. You benefit.', 'We work. You benefit.'],
        ];
    }

    private function servicesIntro(): string
    {
        return '<p>We are passionate about property management – from condominium management and the Austrian Tenancy Act to construction management and general advice – and we make sure you feel well looked after in every respect. Partnership-based cooperation, individual solutions and comprehensive advice come first.</p>';
    }

    private function vacanciesIntro(): string
    {
